.ds-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--pp-home-section-header-gap);
  margin: 0 0 var(--pp-home-section-header-after);
  padding: 0;
}
.ds-section-header__copy {
  align-self: flex-start;
  min-width: 0;
  max-width: 100%;
}
.ds-section-header__heading {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px var(--pp-space-2);
}
.ds-section-header__title {
  margin: 0 0 var(--pp-space-1);
  color: var(--pp-marrom);
  font-family: var(--pp-font-titulo);
  font-size: var(--pp-home-section-title-size);
  font-weight: 400;
  line-height: var(--pp-home-section-title-leading);
  letter-spacing: var(--pp-home-section-title-tracking);
  text-wrap: balance;
  overflow-wrap: anywhere;
}
.ds-section-header__intro {
  margin: 0;
  color: var(--pp-texto-2);
  font-family: var(--pp-font-body);
  font-size: var(--pp-home-section-intro-size);
  line-height: 1.5;
}
.ds-section-header__note {
  color: var(--pp-dourado-escuro);
  font-family: var(--pp-font-nota);
  font-size: var(--pp-home-section-note-size);
  font-weight: 700;
}
.ds-section-header__action {
  display: inline-flex;
  align-items: center;
  gap: var(--pp-space-1);
  min-height: 44px;
  flex: none;
  color: var(--pp-dourado-escuro);
  font-family: var(--pp-font-body);
  font-size: var(--pp-home-section-action-size);
  font-weight: 700;
  white-space: nowrap;
}
.ds-section-header__action svg {
  flex: none;
}
.ds-section-header__action:hover,
.ds-section-header__action:focus-visible {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.ds-section-header__action:focus-visible {
  outline: 3px solid var(--pp-dourado-escuro);
  outline-offset: 4px;
}
@media (max-width: 760px) {
  .ds-section-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .ds-section-header__action {
    align-self: flex-end;
  }
}

.ds-section-header__action{text-decoration:underline;text-underline-offset:4px;text-decoration-color:transparent;transition:text-decoration-color var(--pp-home-action-duration,450ms) var(--pp-ease)}.ds-section-header__action:focus-visible{text-decoration-color:currentColor}@media(hover:hover){.ds-section-header__action:hover{text-decoration-color:currentColor}}@media(prefers-reduced-motion:reduce){.ds-section-header__action{transition:none}}

.ds-add{width:42px;height:42px;display:grid;place-items:center;padding:0;border:0;border-radius:50%;background:var(--pp-marrom);color:var(--pp-surface-card);cursor:pointer}.ds-add:disabled{opacity:.55}.ds-add:active:not(:disabled){transform:scale(.9)}/* Opt-in apenas nas ações dos cards da área do cliente. */
.ds-card-action {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}
.ds-card-action__content {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: inherit;
  pointer-events: none;
}
.ds-card-action__fill {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: inherit;
  padding: inherit;
  border-radius: inherit;
  background: var(--pp-gold);
  color: var(--pp-marrom);
  clip-path: circle(0% at 50% 100%);
  transition: clip-path var(--pp-home-action-duration, 450ms) var(--pp-ease);
  pointer-events: none;
}
.ds-card-action--danger .ds-card-action__fill {
  background: var(--pp-error-bg);
  color: var(--student-danger);
}
.ds-card-action:focus-visible {
  outline: 3px solid var(--pp-dourado-escuro);
  outline-offset: 3px;
}
.ds-card-action:active:not(:disabled):not([aria-disabled="true"]) {
  filter: brightness(0.94);
}
.ds-card-action:is(:disabled, [aria-disabled="true"], .is-loading) > .ds-card-action__fill {
  clip-path: circle(0% at 50% 100%);
  transition: none;
}
.ds-card-action:not(:disabled):not([aria-disabled="true"]):not(.is-loading):focus-visible > .ds-card-action__fill,
.ds-card-action-trigger:focus-visible .ds-card-action__fill {
  clip-path: circle(var(--pp-card-action-radius, 120%) at 50% 100%);
}
@media (hover: hover) {
  .ds-card-action:not(:disabled):not([aria-disabled="true"]):not(.is-loading):hover > .ds-card-action__fill,
  .ds-card-action-trigger:hover .ds-card-action__fill {
    clip-path: circle(var(--pp-card-action-radius, 120%) at 50% 100%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ds-card-action__fill {
    transition: none;
  }
}

